function m(t,n,a,c,h=1.2){const M=Math.max(n,a,1)/t.scale*h,s=2**Math.ceil(Math.log2(Math.max(M/c,1e-6))),o=s*c,r=(n/2-t.tx)/t.scale,e=(a/2-t.ty)/t.scale;return{x:Math.floor((r-o/2)/s)*s,y:Math.floor((e-o/2)/s)*s,size:o,texel:s}}const u=8,x=28,l=20;function f(t){return Math.min(1,Math.max(0,1-t/l))}function i(t,n=x){const a=Math.min(1,Math.max(0,(Math.abs(t)-.75*n)/(.25*n)));return 1-a*a*(3-2*a)}export{x as R,l as S,u as T,i as a,f as r,m as s};
